+        signal,
+        cancelToken,
+        timeout,
+        headers,
+        allowAbsoluteUrls,
+        baseURL,
+        http2Options,
+      } = resolveConfig(config);
+
+      const composedSignal = composeSignals([signal, cancelToken && cancelToken.toAbortSignal()], timeout);
+      const fullPath = buildFullPath(baseURL, url, allowAbsoluteUrls);
