pr_reviewer_data.description:
- Added HTTP2 support for the `http` adapter, activated via the `httpVersion` option
- Fixed streams cancellation bugs

## Code example

```js
    const form = new FormData();

    form.append('foo', '123');

    const {data, headers, status} = await axios.post('https://httpbin.org/post', form, {
      httpVersion: 2,
      http2Options: {
        // rejectUnauthorized: false,
        // sessionTimeout: 1000
      }
      onUploadProgress(e) {
        console.log('upload progress', e);
      },
      onDownloadProgress(e) {
        console.log('download progress', e);
      },
      responseType: 'arraybuffer'
    });
```

```
{
  args: {},
  data: '',
  files: {},
  form: { foo: '123' },
  headers: {
    Accept: 'application/json, text/plain, */*',
    'Accept-Encoding': 'gzip, compress, deflate, br',
    'Content-Length': '155',
    'Content-Type': 'multipart/form-data; boundary=axios-1.12.2-boundary-jzVUkPLpPcPSK2mDNfnc-ONxF',
    Host: 'httpbin.org',
    'User-Agent': 'axios/1.12.2',
    'X-Amzn-Trace-Id': 'Root=1-68ed825e-01408cf044fca43444c0b148'
  },
  json: null,
  url: 'https://httpbin.org/post'
}
